		#region FinaliseButton_Click

		void FinaliseButton_Click(object sender, EventArgs e)
		{
			var adHocServiceJob = AdHocServiceJob;
			if (adHocServiceJob != null)
			{
				adHocServiceJob.FinaliseAdHocServiceJob(this);
			}
		}

