		#region Dispose

		/// <summary>
		/// Clean up any resources being used.
		/// </summary>
		/// <param name="disposing">true if managed resources should be disposed; otherwise, false.</param>
		protected override void Dispose(bool disposing)
		{
			if (disposing)
			{
				if (components != null)
				{
					components.Dispose();
				}

				// Unfortunately since AdHocServiceJobs create a Job Header manually so that we can store the Customer Reference
				// we then need to manually dispose the JobHeader Mutex if the user closes the form without saving.
				var adHocServiceJob = AdHocServiceJob;
				if (adHocServiceJob != null && !adHocServiceJob.IsDeleted)
				{
					var jobHeader = adHocServiceJob.JobHeader;
					if (jobHeader != null)
					{
						jobHeader.Dispose();
					}
				}
			}

			base.Dispose(disposing);
		}

